import itertools

def solve_small(n):
    # Try all permutations of 1..n^2
    # and for each, calculate the number of good paths.
    # For n=2, there are 4! = 24 permutations.
    # For n=3, there are 9! = 362880 permutations.
    min_paths = float('inf')
    for p in itertools.permutations(range(1, n**2 + 1)):
        grid = [p[i:i+n] for i in range(0, n**2, n)]

        # W[r][c] = number of paths starting at (r,c)
        # Condition (i): only adjacent to fields with larger numbers
        # Condition (ii), (iii): subsequent fields are adjacent and increasing

        # To calculate W[r][c], we can use DP since it's a DAG
        # The DAG edges are (r,c) -> (nr,nc) if |r-nr|+|c-nc|=1 and grid[nr][nc] > grid[r][c]
        # W(r,c) = 1 + sum(W(nr,nc) for all such neighbors)

        # We need to calculate W in decreasing order of grid values
        W = [[0]*n for _ in range(n)]
        # Sort the cells by their values in descending order
        cells = []
        for r in range(n):
            for c in range(n):
                cells.append((grid[r][c], r, c))
        cells.sort(key=lambda x: x[0], reverse=True)

        for val, r, c in cells:
            W[r][c] = 1
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n:
                    if grid[nr][nc] > val:
                        W[r][c] += W[nr][nc]

        # Total good paths: sum(W[r][c] for all cells (r,c) satisfying condition (i))
        total_good_paths = 0
        for r in range(n):
            for c in range(n):
                # Condition (i): all neighbors have larger numbers
                is_starting_field = True
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < n:
                        if grid[nr][nc] < grid[r][c]:
                            is_starting_field = False
                            break
                if is_starting_field:
                    total_good_paths += W[r][c]

        if total_good_paths < min_paths:
            min_paths = total_good_paths

    return min_paths

