import itertools

def count_good_paths(board):
    rows = len(board)
    cols = len(board[0])

    # Find starting cells
    starting_cells = []
    for r in range(rows):
        for c in range(cols):
            is_starting = True
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if board[nr][nc] < board[r][c]:
                        is_starting = False
                        break
            if is_starting:
                starting_cells.append((r, c))

    # DP to count increasing paths starting at each cell
    # Since it's a DAG, we can use memoization
    memo = {}
    def count_paths(r, c):
        if (r, c) in memo:
            return memo[(r, c)]

        count = 1
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if board[nr][nc] > board[r][c]:
                    count += count_paths(nr, nc)

        memo[(r, c)] = count
        return count

    total_paths = 0
    for r, c in starting_cells:
        total_paths += count_paths(r, c)
    return total_paths

def solve_min_paths(rows, cols):
    min_paths = float('inf')
    nums = list(range(1, rows * cols + 1))
    for p in itertools.permutations(nums):
        board = [p[i*cols : (i+1)*cols] for i in range(rows)]
        min_paths = min(min_paths, count_good_paths(board))
    return min_paths

